(() => {
  const pick=(zh,en)=>language==="zh"?zh:en;
  const api=window.SYSTEM_OVERVIEW_SECTIONS=window.SYSTEM_OVERVIEW_SECTIONS||{};
  const text=(v)=>typeof v==="object"&&v!==null?(language==="zh"?(v.zh||v.en):(v.en||v.zh)):String(v||"");
  const metric=(v,zh,en,tone="")=>`<div class="reader-metric ${tone}"><b>${esc(String(v??0))}</b><span>${pick(zh,en)}</span></div>`;
  const flow=(items)=>`<div class="reader-flow">${items.map((x,i)=>`${i?'<i>→</i>':''}<div><span>${String(i+1).padStart(2,"0")}</span><b>${x[0]}</b><small>${x[1]}</small></div>`).join("")}</div>`;
  const io=(a,b,c,d,e,f)=>`<div class="reader-contract"><div><small>${pick("输入","INPUT")}</small><span>${pick(a,b)}</span></div><i>→</i><div><small>${pick("核心判断","DECISION")}</small><span>${pick(c,d)}</span></div><i>→</i><div><small>${pick("阶段产出","OUTPUT")}</small><span>${pick(e,f)}</span></div></div>`;
  const researchMemory=(state)=>window.RESEARCH_MEMORY_WIKI||state.research_memory_wiki||{};
  const paperDevelopmentGuidance=(state)=>(researchMemory(state).entries||[]).find(row=>row?.kind==="PAPER_DEVELOPMENT_GUIDANCE")||{};
  const paperDevelopmentCards=(state)=>{const g=paperDevelopmentGuidance(state),dims=(g.guidance?.dimensions||[]);return dims.map(row=>`<div><b>${esc(language==="zh"?(row.title_zh||row.key):(row.title_en||row.key))}</b><span>${esc(language==="zh"?(row.goal_zh||""):(row.goal_en||""))}</span></div>`).join("");};
  const iclrTemplate=()=>window.ICLR_AGENT_PAPER_TEMPLATE||{};
  const iclrTemplatePanel=()=>{const t=iclrTemplate(),pages=t.page_budget_main_body||[],lanes=t.experiment_lanes||[],refs=t.derived_from||[],writing=t.writing_rules||{};if(!t.template_id)return "";const pageCards=pages.map(x=>`<div class="iclr-template-page"><b>${esc(x.section||"")}</b><span>${esc(String(x.pages||0))}p · ${esc(x.job||"")}</span></div>`).join("");const laneCards=lanes.map(x=>`<div class="iclr-template-lane" data-iclr-lane="${esc(x.id||"")}"><b>${esc(x.id||"")} · ${esc(x.name||"")}</b><span>${esc(x.question||"")} ${x.required?`· ${pick("必选","required")}`:`· ${pick("可选","optional")}`}</span></div>`).join("");return `<section class="iclr-paper-template"><header><span class="system-kicker">ICLR PAPER TEMPLATE V1</span><h4 data-toc="false">${pick("固定论文论证与实验骨架，不照抄某一篇论文","A fixed argument and experiment scaffold, not imitation of one paper")}</h4><p>${pick(`从 ${refs.length} 篇 ICLR Agent / memory / self-improvement / evaluation 样板中抽取共性：第一页面向真实问题，方法先讲 intuition，实验至少覆盖主比较、消融、机制、边界/迁移、失败和成本。模板约束“怎么写、实验怎么设计”，不授权实际运行。`,`Distilled from ${refs.length} ICLR exemplars across agents, memory, self-improvement, and evaluation: make the real problem visible on page one, explain method intuition before modules, and cover main comparison, ablation, mechanism, boundary/transfer, failures, and cost. This governs writing and experiment planning; it does not authorize execution.`)}</p></header><div class="preflight-card-grid iclr-template-pages">${pageCards}</div><div class="preflight-card-grid iclr-template-lanes">${laneCards}</div><div class="reader-rule"><b>${pick("结果段固定写法","Fixed result-paragraph order")}</b><span>${esc(writing.result_paragraph||"answer → evidence → interpretation → boundary")}</span></div><details><summary><b>${pick("查看 8 篇 ICLR 样板及各自学到什么","Open the eight ICLR exemplars and extracted lessons")}</b></summary><div class="preflight-card-grid iclr-template-references">${refs.map(x=>`<div><b>${esc(x.title||x.key||"")}</b><span>${esc(x.venue||"")} · ${esc(x.lesson||"")}</span></div>`).join("")}</div></details><small>${esc(t.template_id)} · SHA ${esc(String(t.template_sha256||"").slice(0,12))} · ${pick("scientific / experiment / GPU authority 全部为 0","scientific / experiment / GPU authority = 0")}</small></section>`;};
  const readerOutputZh={overview:"看懂整条科研到投稿流程和每一步由谁决定","problem-discovery":"明确：继续研究、缺证据暂缓，或已有解释因此停止","scientific-design":"冻结 Problem–Insight、贡献归因、最小充分干预与证据梯度","experiment-compile":"明确：这个最小实验可以启动，或具体哪项条件没满足","validation-scale":"明确失败发生在哪一层，并决定修实验、修方法、收缩范围或停止","paper-evidence":"冻结 scientific paper contract，并让每条主张都能追到证据","paper-construction":"Story Search 形成成稿，并先完成 Post-Draft Integrity","review-repair":"完成完整性核验、双模式 Mock PC、定向修复、re-audit 与 Claim Audit","submission-closure":"完成 Prebuttal、Submission Ready、人工投稿与 Rebuttal 交接","system-learning":"保存失败原因、重开条件和下次先做的廉价检查"};
  const authorityZh={advisory:["建议层","只能提出建议","AI 负责查文献撞车、找更强基线、指出实验漏洞和拒稿风险"],"machine-gated":["机器检查层","满足条件才能继续","机器只检查资源是否值得花、评测协议是否可靠、实验启动条件是否满足"],"human-scientific":["人工决策层","必须由人工决定","改变核心主张、核心方法、预算规模和最终投稿结论都必须由人工负责人确认"]};
  const phase=(n,id,kicker,zhTitle,enTitle,zhBody,enBody,inner)=>{
    // New reader copy passes already-localized title/body plus HTML content (6 args),
    // while older callers pass separate zh/en title/body plus HTML (8 args).
    // Accept both forms so a copy-only frontend rewrite cannot silently drop a phase body.
    const compact = inner === undefined && enBody === undefined;
    const title = compact ? zhTitle : pick(zhTitle,enTitle);
    const body = compact ? enTitle : pick(zhBody,enBody);
    const content = compact ? zhBody : inner;
    return `<section class="reader-phase system-section" id="${id}"><div class="reader-phase-head"><div><span class="system-kicker">${String(n).padStart(2,"0")} · ${kicker}</span><h3>${title}</h3><p>${body}</p></div><div class="reader-phase-number">${String(n).padStart(2,"0")}</div></div>${content||""}</section>`;
  };

  api.wrapDeepDive=(zh,en,body)=>`<details class="system-deep-dive"><summary><span>${pick(zh,en)}</span><small>${pick("展开审计细节（可选）","open optional audit detail")}</small></summary><div class="system-deep-dive-body">${body||""}</div></details>`;

  api.renderReaderRoadmap=(state)=>{
    const arch=state.system_architecture||{},groups=arch.reading_groups||[],temporal=new Map((arch.temporal_flow||[]).map(x=>[x.key,x]));
    const cards=groups.map((g,i)=>{const stages=(g.stage_keys||[]).map(k=>temporal.get(k)).filter(Boolean);const range=g.orientation_only?pick("阅读入口 · 不增加科学 Gate","orientation · no new gate"):(stages.length===1?pick(`第 ${stages[0].index} 阶段`,`Stage ${stages[0].index}`):pick(`第 ${stages[0]?.index||"?"}–${stages[stages.length-1]?.index||"?"} 阶段`,`Stages ${stages[0]?.index||"?"}–${stages[stages.length-1]?.index||"?"}`));const output=language==="zh"?(readerOutputZh[g.key]||String(g.output||"--")):String(g.output||"--");return `<a class="reader-roadmap-card ${g.orientation_only?"orientation":""}" href="#chapter-${esc(g.key||"")}"><header><span>${String(g.index||i+1).padStart(2,"0")}</span><small>${esc(range)}</small></header><b>${esc(text(g.label))}</b><p>${esc(text(g.question))}</p><footer>${esc(output)}</footer></a>`}).join("");
    return `<section class="reader-roadmap system-section" id="overview"><div class="preflight-heading"><div><span class="system-kicker">${pick("10 章阅读路线","READ THIS PAGE IN 10 CHAPTERS")}</span><h3>${pick("沿一条主线看完：Problem → Insight → 最小干预 → 决定性实验 → 证据 → 成稿 → 审稿","Follow one path: Problem → Insight → minimal intervention → decisive experiment → evidence → manuscript → review")}</h3><p>${pick(`这 ${groups.length||10} 章按真实工作顺序排列：先找重要但未解释清楚的问题，确认贡献新在哪一层，再设计最小充分干预和决定性实验；证据冻结后才做 Story Search 和成稿，初稿先经过 Post-Draft Integrity，再进入独立 Mock PC、定向修稿、re-audit、Claim Audit、PDF QA、Prebuttal 和人工投稿。页面里的 ${arch.summary?.temporal_stages||21} 个机器阶段是更细的 canonical lifecycle。`,`These ${groups.length||10} chapters follow the real work order: find an important under-explained problem, attribute the true contribution layer, design the minimum sufficient intervention and decisive experiment, then freeze the evidence. After Paper Evidence, Story Search and manuscript construction are followed by Post-Draft Integrity before independent Mock PC, Targeted Repair, re-audit, Claim Audit, PDF QA, Prebuttal, and external-human submission. The ${arch.summary?.temporal_stages||21} machine stages are the finer canonical lifecycle.`)}</p></div><div class="preflight-lock"><b>${groups.length||10}</b><span>${pick("个阅读章节","reader chapters")}</span></div></div><div class="reader-roadmap-grid">${cards}</div></section>`;
  };

  api.renderAuthorityModel=(state)=>{const rows=state.system_architecture?.authority_boundaries||[];return `<section class="reader-authority system-section"><div><span class="system-kicker">${pick("统一权限模型","ONE AUTHORITY MODEL")}</span><h3>${pick("谁能提建议、谁能启动实验、谁能改论文结论，要分开","Separate who may advise, launch, and change scientific claims")}</h3><p>${pick("AI 可以指出撞车、实验漏洞或更强基线，但不能自己决定“论文成立”或“给 GPU”。机器检查只能确认预先写好的条件是否满足。只有人工负责人可以扩大预算、改变核心方法、修改论文主张或做最终投稿决定。","AI may flag prior-work collisions, experiment flaws, or stronger baselines, but it cannot declare a paper valid or grant GPU use. Machine checks only verify predefined conditions. Human owners alone may expand budget, change the core method, alter paper claims, or make the final submission decision.")}</p></div><div class="reader-authority-grid">${rows.map(r=>{const zh=authorityZh[r.key]||[text(r.label),text(r.label),(r.examples||[]).join(" · ")];return `<article><small>${esc(pick(zh[0],String(r.key||"").toUpperCase()))}</small><b>${esc(pick(zh[1],text(r.label)))}</b><p>${esc(pick(zh[2],(r.examples||[]).join(" · ")))}</p></article>`}).join("")}</div></section>`};

  api.renderProblemDiscoveryPhase=(state)=>{
    const p=state.paper_first_primary_evidence?.summary||{},g=state.paper_first_problem_generator?.summary||{},pf=state.paper_first_pre_f0_queue?.summary||{},pfs=state.paper_first_pre_f0_problem_falsifier_preflight?.summary||{},q=state.paper_first_problem_gate_queue?.summary||{},f=state.paper_first_fresh_phenomenon_portfolio?.summary||{};
    const portfolio=state.research_candidate_portfolio?.summary||{},funnel=state.search_funnel_telemetry||{},funnelSummary=funnel.summary||{},bottleneck=funnel.bottleneck||{},assurance=state.research_harness_assurance?.summary||{};
    const body=`${io("论文原文、作者发布的代码/数据、真实实验结果和已验证失败案例","Primary papers, author-released assets/data, real experiment results, and verified failure cases","先确认异常现象真实存在；再广泛搜索不同问题、合并重复项、修复可救候选；最后用同样信息检验最强已有解释","First confirm that the failure is real, then search broadly for distinct paperable problems, repair and eliminate them progressively, and apply strict same-information reduction at the end","候选问题 → 修复后的候选 → 低成本预验证 → 正式问题检查","High-recall seeds → repaired candidates → zero-authority pre-F0 → formal Problem Gate")}${flow([[pick("① 广泛搜索不同问题","① BROAD SEARCH · 10 PRIMITIVES"),pick("一次批量提出不同类型的候选问题，避免只围绕第一个直觉反复改写","do not generate one idea at a time; batch seeds from contradiction, repeated failure, broken assumptions, boundaries, identifiability, missing decision objects, interactions, structural analogy, new capabilities, and longitudinal emergence")],[pick("② 合并重复项，保留真正不同的分支","② DEDUP + DIVERSITY"),pick("近义题目合并，但机制、信息条件、测量对象或适用范围不同的分支继续保留","merge near-duplicates while preserving branches that differ in mechanism, information, measurement object, or regime")],[pick("③ 先攻击，再尝试修复","③ ATTACK → REPAIR → SPLIT"),pick("独立评审先给出最强反对意见；能通过改变一个科学轴修复的就生成新候选，只有核心原理已经被确切解释或否定才永久停止","reviewer states the strongest objection, then changes one scientific axis and creates repair children; only exact principle closure is terminal")],[pick("④ 分开判断不同类型的贡献","④ PAPERABILITY · P/M/E/B/T/S"),pick("原理被已有理论解释，并不自动意味着方法、经验现象、评测、理论保证或系统能力也没有贡献","score principle P, method M, empirical E, benchmark B, theory T, and system S separately; reducing P does not automatically erase M/E/B/T/S")],[pick("⑤ 先做最便宜的预验证","⑤ CHEAP PRE-F0"),pick("若只缺一个决定性事实，先用低成本测试补齐；数据支持、实验协议或实现条件不足，只修对应问题，不把候选永久判死","when one decisive fact is missing, run a zero-authority cheap falsifier; support/protocol/realization failures repair only their own layer")],[pick("⑥ 最后才做正式科学筛选","⑥ TRY EXISTING EXPLANATIONS, THEN EXACT REDUCTION + PROBLEM GATE"),pick("即使低成本测试为阳性，也要让最强成熟解释获得完全相同的信息重新比较；只有正式问题检查通过，才进入下一阶段科学设计","even a positive pre-F0 must rerun the strongest same-information reduction; only the formal gate may enter Paper Design")]])}<div class="reader-metrics">${metric(p.verified||0,"已核验第一手证据","verified primary evidence")}${metric(g.raw_seeds||0,"本轮初始候选","broad-search seeds")}${metric(g.semantic_unique_seeds||0,"去重后的不同问题","semantic-unique problems")}${metric(g.repair_children||0,"评审修复后的新候选","reviewer repair children")}${metric(pf.queued||g.pre_f0_eligible||0,"进入低成本预验证","zero-authority pre-F0 candidates")}${metric(pfs.hold_support_unavailable||0,"因验证条件不足暂缓","pre-F0 support holds")}${metric(pfs.support_qualified||0,"已具备验证条件","support-ready pre-F0")}${metric(q.passed_problem_gate||0,"通过正式问题检查","passed formal Problem Gate")}</div><div class="reader-rule"><b>${pick("负责多想候选的模型，不能同时当最终裁判","ARIS-inspired harness: separate search firepower from the jury")}</b><span>${pick(`候选生成只负责扩大搜索范围，机械去重只负责合并重复项；最终反对意见必须来自独立模型。独立评审说“没有发现阻断”也不等于科学结论自动通过。当前独立性检查=${assurance.passed||0}/${assurance.checks||0}，违规=${assurance.resolved_model_independence_violations||0}。`,`Fan-out expands candidates and deterministic dedup only merges duplicates. Only a resolved-model-independent jury may issue BLOCK/CLEAR, and CLEAR is still not scientific PASS. Current harness invariants=${assurance.passed||0}/${assurance.checks||0}; independence violations=${assurance.resolved_model_independence_violations||0}.`)}</span></div><div class="reader-rule"><b>${pick("当前搜索漏斗卡在哪里","Where the current search funnel is actually blocked")}</b><span>${pick(`第一手证据 ${funnelSummary.primary_verified||0} 条 → 初始候选 ${funnelSummary.raw_seeds||0} 条 → 进入低成本预验证 ${funnelSummary.pre_f0_queued||0} 条 → 已具备验证条件 ${funnelSummary.pre_f0_support_qualified||0} 条 → 通过正式问题检查 ${funnelSummary.problem_gate_passed||0} 条。当前组合中保留 ${portfolio.visible_candidates||0} 条候选，其中继续推进=${portfolio.active_problem_lines||0}、因缺条件暂缓=${portfolio.search_holds||0}。`,`Primary evidence=${funnelSummary.primary_verified||0} → raw seeds=${funnelSummary.raw_seeds||0} → pre-F0=${funnelSummary.pre_f0_queued||0} → support-ready=${funnelSummary.pre_f0_support_qualified||0} → Problem Gate PASS=${funnelSummary.problem_gate_passed||0}. Current bottleneck=${bottleneck.key||"--"}. The portfolio keeps ${portfolio.visible_candidates||0} candidates visible: active=${portfolio.active_problem_lines||0}, search hold=${portfolio.search_holds||0}; capacity targets are scheduling hints only and never auto-promote a candidate.`)}</span></div><div class="reader-rule"><b>${pick("前面可以多想、多修；正式推进时标准仍然严格","The standard is unchanged; strict rejection now happens at the right stage")}</b><span>${pick("候选早期允许不完整，也允许评审后修复；一旦进入正式推进，低成本预验证没有论文、方法、实验或 GPU 授权，阳性结果还必须与同信息条件下的最强成熟解释重新比较。只有核心原理已经被可靠否定，才会永久写入死路记忆。","The first half optimizes recall: candidates may be incomplete, reviewers may repair them, and a reduced P axis can still leave M/E/B/T/S to test. The second half remains strict: pre-F0 grants no Paper/Method/Experiment/P0/GPU authority, and a positive result must return to exact same-information reduction. STOP remains typed as REALIZATION_STOP, SUPPORT_STOP, PROTOCOL_STOP, or PRINCIPLE_STOP; only PRINCIPLE_STOP may enter persistent dead-end memory.")}</span></div>`;
    return phase(2,"problem-discovery",pick("先广泛找问题，再逐步收紧证据要求","DECIDE WHETHER A NEW PROBLEM EXISTS · SEARCH BROADLY, REPAIR, TEST CHEAPLY, THEN JUDGE STRICTLY"),pick("新候选不会一上来就被严格淘汰：先广泛搜索，再去重和修复，最后才做正式科学筛选","A newborn idea no longer faces final review immediately: broaden the search first, repair and split it through review, then apply same-information reduction and the formal Problem Gate."),pick("目标不是每轮硬凑一个新方向，而是先保证搜索足够广，再清楚记录每个候选为什么继续、为什么暂缓、为什么被已有解释覆盖。只有最后的正式问题检查通过，才进入科学贡献设计。","The goal is not to guarantee an accepted idea every round. It is to ensure broad search actually happened and to show whether each candidate was lost at deduplication, reviewer repair, pre-F0, exact reduction, or the formal Problem Gate."),body);
  };

  api.renderPaperDesignPhase=(state)=>{
    const w=state.paper_first_workflow?.summary||{},p=state.principle_layer?.summary||{},v=state.paper_visual_evidence?.summary||{},a=state.ai_consultation_clinic?.summary||{},reason=state.research_reasoning_layer?.summary||{};
    const body=`${io("已经确认值得研究的具体问题","A concrete problem that survived prior-work and theory checks","能否把问题压缩成“大家看到 X，但缺少 Y 这个解释；如果 Y 是原因，只改 Z 就应该出现可预测变化”？贡献究竟新在哪一层？","Can the problem be compressed into: people observe X, Y is the missing explanation, and changing only Z should create a predictable effect? Which contribution layer is actually new?","Problem–Insight Certificate + Contribution Attribution + 最小充分干预 + 证据计划","Problem–Insight Certificate + Contribution Attribution + minimum sufficient intervention + evidence plan")}${flow([[pick("问题与未解释现象","PROBLEM + UNDER-EXPLAINED PHENOMENON"),pick("先说明为什么重要、现有工作已经观察到什么、真正还没解释清楚什么","state why the problem matters, what is already observed, and what remains under-explained")],[pick("贡献归因","CONTRIBUTION ATTRIBUTION"),pick("分别判断 Problem / Phenomenon / Insight / Mechanism / Method / Evaluation / Theory / System 哪一层是 NEW、KNOWN 或 UNCERTAIN","type each contribution layer as NEW, KNOWN, or UNCERTAIN rather than assigning one novelty score to the whole idea")],[pick("最小充分干预","MINIMUM SUFFICIENT INTERVENTION"),pick("先尝试由 Insight 直接推出的 rule / filter / constraint / reweight；复杂模块必须带来额外可证伪预测","try the simplest rule/filter/constraint/reweight implied by the insight; extra complexity must add a falsifiable prediction")],[pick("简化归因","SIMPLIFICATION ATTRIBUTION"),pick("简单 baseline 复现 method 只削弱 Method claim；只有连 Problem/Insight 等 scientific object 也被吸收，才考虑整篇 STOP","a simple baseline that reproduces the method weakens the method claim only; whole-paper STOP requires reduction of the scientific object itself")],[pick("Insight Evidence Ladder","EVIDENCE LADDER"),pick("按 Phenomenon → Controlled reproduction → Prediction → Minimal intervention → Strongest alternative → Generalization → Boundary 组织证据","plan evidence as phenomenon → controlled reproduction → prediction → minimal intervention → strongest alternative → generalization → boundary")]])}<div class="reader-metrics">${metric(w.paper_design_passed||0,"论文设计已通过","paper designs passed")}${metric(p.certificates_passed||0,"机制假设检查已通过","principle checks passed")}${metric(reason.contribution_replay_cases||0,"贡献归因历史回放","contribution-attribution replay cases")}${metric(reason.contribution_replay_wrong_whole_paper_stops||0,"历史回放整篇误杀","wrong whole-paper stops in replay",reason.contribution_replay_wrong_whole_paper_stops?"warn":"good")}${metric(v.planned_main_visualizations||0,"已规划主文证据图","planned main evidence figures")}</div>${iclrTemplatePanel()}<div class="reader-rule"><b>${pick("方法简单什么时候是优点？","When is a simple method a strength?")}</b><span>${pick("如果问题重要、现象真实、Insight 能做出额外预测，而一个极简干预恰好由这个 Insight 直接推出，那么方法简单是 scientific compression 的结果，不需要为了“像论文”再加模块。只有 simple baseline 连核心 Insight 都已经解释掉，才应该真正缩减或停止论文。","When the problem matters, the phenomenon is real, the insight makes additional predictions, and a minimal intervention follows directly from it, simplicity is scientific compression rather than a weakness. Do not add modules merely to look more paper-like; narrow or stop only when the simple baseline also absorbs the core insight.")}</span></div><div class="reader-rule"><b>${pick("局部实验把核心方法改了怎么办","If the pilot changes the core method")}</b><span>${pick("一旦实验结果迫使我们换掉核心机制，就把它当成新版本重新检查 Contribution Attribution、closest work、最强基线和实验设计。旧方法对应的全量实验计划不能直接沿用。","If a pilot forces a change to the core mechanism, treat it as a new version and recheck contribution attribution, closest work, strongest baselines, and experiment design. Do not reuse the old full-experiment plan automatically.")}</span></div>`;
    return phase(3,"scientific-design",pick("先压缩 Problem–Insight，再设计最小方法和证据链","COMPRESS THE PROBLEM–INSIGHT, THEN DESIGN THE MINIMAL METHOD AND EVIDENCE"),pick("问题通过后，先确认真正的贡献层和 Insight，再开始实现","After the problem passes, identify the true contribution layer and insight before implementation"),pick("这一阶段不要求方法看起来复杂，而要求科学对象足够清楚：问题为什么重要、缺失的解释是什么、最小干预为什么从 Insight 推出来、它会产生什么可证伪预测、最强简单解释能吸收哪一层贡献。之后再把这些预测逐一映射到实验、图和表。","This stage does not reward method complexity. It requires a crisp scientific object: why the problem matters, what explanation is missing, why the minimal intervention follows from the insight, which falsifiable predictions it makes, and which contribution layer the strongest simplification can actually absorb. Those predictions are then mapped to experiments, figures, and tables."),body);
  };

  api.renderExperimentCompilePhase=(state)=>{
    const e=state.p0_economy_gate?.summary||{},c=state.pre_experiment_compiler?.summary||{},gf=c.gate_failures||{};
    const body=`${io("已经写清的主张、方法、基线和实验计划","Frozen claim, method, baselines, and experiment plan","这个最小实验无论成功或失败，都会改变下一步吗？数据、真值、统计和运行条件都可靠吗？","Would either outcome change the next action, and are the data, truth, statistics, and runtime reliable?","允许启动，或写清具体阻断原因","Launch approval, or a concrete blocker")}${flow([[pick("先问值不值得跑","IS THE RUN WORTH IT?"),pick("数据/环境可用 · 最强简单基线 · 正确比较单位 · 结果会改变决策","usable data/environment · strongest simple baseline · correct comparison unit · decision-changing result")],[pick("防止实验自己骗自己","PREVENT SELF-DECEPTION"),pick("隐藏测试提前封存 · 真值独立 · 信息和预算匹配","seal hidden tests · independent truth · matched information and budget")],[pick("先证明更新能改变行为","CHECK THE UPDATE WORKS"),pick("Prompt、记忆或模块若产生不了目标变化，就不比较复杂方法","stop if the update surface cannot realize the target effect")],[pick("写清执行和恢复","EXECUTION + RECOVERY"),pick("目标 · 依赖 · 检查点 · 输出文件 · 恢复位置","objective · dependencies · checkpoints · outputs · recovery point")],[pick("最后八类启动检查","FINAL LAUNCH CHECKS"),pick("参数 · 基线能力 · 能否区分机制 · 样本量 · 计算 · 吞吐 · 恢复 · 超时/步数上限解释","parameters · baseline competence · identifiability · sample size · compute · throughput · recovery · timeout/cap semantics")]])}<div class="reader-metrics">${metric(e.economy_ready||0,"最小实验值得运行","smallest test worth running")}${metric(c.protocol_validity_pass||0,"防泄漏/公平比较检查通过","leakage/fair-comparison checks passed")}${metric(c.updater_prerequisite_pass||0,"更新确实能产生目标变化","update can realize the target effect")}${metric(c.execution_ready||0,"当前可以启动实验","currently launchable",c.execution_ready?"good":"warn")}</div><div class="reader-rule"><b>${pick("当前最常见的三个阻断原因","Three common blockers")}</b><span>${pick(`${gf.baseline_competence||0} 个候选：简单基线本身无法完成任务；${gf.mechanism_identifiability||0} 个候选：当前实验无法区分两种解释；${gf.outcome_semantics||0} 个候选：结果可能被超时或步数上限误读。这些问题只说明当前实验设计不能用，不会自动证明科学想法错误。`,`baseline cannot perform the task=${gf.baseline_competence||0}; experiment cannot distinguish the explanations=${gf.mechanism_identifiability||0}; outcome could be misread because of timeout/caps=${gf.outcome_semantics||0}. These invalidate the current experiment design; they do not automatically prove the paper idea false.`)}</span></div>`;
    return phase(4,"experiment-compile",pick("GPU 前先把最小实验检查清楚","CHECK THE SMALLEST TEST BEFORE GPU"),pick("不要先跑大实验；先找一个最便宜、结果会改变决策的小实验","Do not start with the large run; find the cheapest test whose result would change the decision"),pick("启动前要确认：数据和环境能产生目标效应，最强基线拿到同样的信息和预算，真值来自独立来源，样本量足够，而且代码、模型和资源能稳定运行。任何一项不满足，就先修设计或停止当前实验。","Before launch, confirm that data/environment can realize the effect, the strongest baseline gets the same information and budget, truth is independent, sample size is sufficient, and code/model/resources run reliably. Fix or stop the current experiment if any check fails."),body);
  };

  api.renderValidationScalePhase=(state)=>{
    const g=state.research_governance_v2||{},it=state.experiment_iteration?.summary||{},l=state.p0_decision_ledger?.summary||{};
    const body=`${io("已批准的小规模实验结果 + 完整原始轨迹/日志","Approved local results + complete raw traces/logs","失败发生在运行、实验可辨识性、优化、测量桥、方法实现、假设/范围还是核心原理？","Did failure occur in execution, experiment identifiability, optimization, operationalization, method realization, assumption/scope, or the core principle?","具体失败层、证据和下一步；若方法稳定则冻结版本并进入全量实验","Concrete failure layer, evidence, and next action; if stable, freeze the method version and proceed to full experiments")}${flow([[pick("先确认现象能被测到","VERIFY THE PHENOMENON"),pick("小实验先回答目标现象是否存在、是否可区分","first test whether the phenomenon exists and can be distinguished")],[pick("只更新失败的那一层","UPDATE ONLY THE FAILED LAYER"),pick("运行、实验可辨识、优化、测量桥、方法实现、假设/范围、核心原理分别判断","separate execution, experiment identifiability, optimization, operationalization, method realization, assumption/scope, and core principle")],[pick("方法稳定后冻结版本","FREEZE A STABLE METHOD"),pick("保存方法与实验计划版本，不再随结果临时修改","save method and plan versions; stop outcome-driven changes")],[pick("最后才跑全量实验","FULL EXPERIMENTS LAST"),pick("主表 + 最强基线 + 消融 + 复现 + 效率","main table + strongest baseline + ablation + replication + efficiency")]])}<div class="reader-metrics">${metric((g.stages||[]).length||7,"后台验证步骤","backend validation stages")}${metric(it.identifiable||0,"能可靠区分结论的结果","results that distinguish the claim")}${metric(it.belief_updates_allowed||0,"允许改变科学结论","scientific conclusions allowed to change")}${metric(l.launchable||0,"现在允许启动","currently launchable")}</div><div class="reader-rule"><b>${pick("什么时候才允许说“这个原理走不通”","When a principle may be declared a dead end")}</b><span>${pick("只有实验确实测到了原理承诺的现象、数据和真值可靠、最强基线公平、方法实现有效、适用范围没有设错，而且核心预测仍被直接反驳，才允许停止原理。单纯一次实验没过不能推出“想法错了”。","A principle may be stopped only when the experiment really measures its promised phenomenon, data and truth are reliable, the strongest baseline is fair, the implementation is competent, the scope is correct, and the core prediction is still directly contradicted. One failed run is never enough to conclude that the scientific idea is false.")}</span></div>`;
    return phase(5,"validation-scale",pick("先小规模运行，弄清失败原因，再决定是否扩量","RUN SMALL, DIAGNOSE, THEN DECIDE WHETHER TO SCALE"),pick("实验没过时，先判断是实验、方法，还是科学原理出了问题","When a test fails, identify exactly what failed before changing the science"),pick("读者层先分三类：运行或实验设计出了问题、方法或实现出了问题、核心科学预测真的被可靠否定。后台再把它细分为七个失败层。只有最后一种在完整反证和替代解释都成立时，才允许修改核心科学判断；一次实验没过不能直接写成“想法错了”。","Every negative result is forced into one of seven layers: execution, experiment identifiability, optimization sufficiency, principle-to-measurement/representation bridge, method realization, assumption/scope, or core principle. The first six repair only their own layer; the seventh may update the core principle only when both the full falsifier and a positive counter-explanation hold."),body);
  };

  api.renderPaperEvidencePhase=(state)=>{
    const paper=state.asset_first_stri_paper_ready||{},s=paper.summary||{},v=state.paper_visual_evidence?.summary||{};
    const body=`${io("全量实验结果、原始数据、分析脚本和论文草稿","Full results, raw data, analysis scripts, and manuscript draft","论文每条主张是否都有直接证据？图表能否重新生成？有没有说得比证据更宽？","Does every claim have direct evidence, can figures be regenerated, and is any claim broader than the evidence?","冻结 scientific paper contract + 内容寻址证据包","Frozen scientific paper contract + content-addressed evidence package")}${flow([[pick("最强基线","STRONGEST BASELINE"),pick("证明提升不是更简单方法就能做到","show that a simpler method cannot explain the gain")],[pick("消融","ABLATION"),pick("删掉关键组件后效果应消失或明显减弱","remove the key component and show the effect weakens")],[pick("为什么有效、哪里失效","WHY / WHERE IT FAILS"),pick("机制分析 · 失败案例 · 敏感性 · 不确定性","mechanism · failure cases · sensitivity · uncertainty")],[pick("主文图表","MAIN FIGURES"),pick("每张图都追到原始数据、脚本和图注","trace every figure to data, script, and caption")],[pick("证据合同冻结","FREEZE EVIDENCE CONTRACT"),pick("主张 · limitation · evidence refs · unsupported claims 全部固定后才交给 Paper Acceptance","freeze claims, limitations, evidence refs, and unsupported claims before Paper Acceptance")]])}<div class="reader-metrics">${metric(s.paper_ready||0,"科学证据包已闭环","scientific evidence package closed",s.paper_ready?"good":"warn")}${metric(s.claims_supported||0,"有证据支持的核心主张","core claims with evidence")}${metric(s.paper_quality_content_addressed_files||0,"固定哈希版本的关键文件","key files pinned to fixed hashes")}${metric(s.paper_quality_main_visualizations||v.stri_completed_main_visualizations||0,"主文证据图","main evidence figures")}${metric(`${s.official_qa_checks_passed||0}/${s.official_qa_checks_total||0}`,"已有工件格式检查","existing artifact format checks")}</div><div class="reader-rule"><b>${pick("论文结论必须从“主张账本”读取，不能直接看结果文件自由发挥","The manuscript reads claims from a Claim Ledger, not directly from result files")}</b><span>${pick("每条主张先绑定具体证据，再被裁决为“充分支持”“仅支持窄范围”“被反驳”或“仍不确定”。只有前两类允许写成肯定式结论；后两类必须保留为负面或不确定结果，不能为了让论文看起来更完整而改写成正向主张。","Each claim is first bound to concrete evidence IDs and adjudicated as SUPPORTED, SUPPORTED_NARROWLY, REFUTED, or INCONCLUSIVE. Only the first two permit affirmative wording; REFUTED and INCONCLUSIVE must remain negative or uncertain rather than being rewritten into positive claims for paper readiness.")}</span></div><div class="reader-rule"><b>${pick("STRI 展示了科学证据怎样冻结成论文证据合同","STRI is the worked example for freezing scientific evidence into a Paper Contract")}</b><span>${pick(`当前 ${s.paper_quality_content_addressed_files||0} 个关键文件已经固定版本，因此数据、脚本、图和论文源文件都能核对到同一份内容；未完成证据项=${s.paper_quality_evidence_debt||0}。这只说明科学证据已经闭环；论文是否真的准备好投稿，还要以后续独立的投稿流程状态为准。`,`The current ${s.paper_quality_content_addressed_files||0} key files are hash-pinned, so data, scripts, figures, and source files resolve to fixed content; unfinished evidence items=${s.paper_quality_evidence_debt||0}. This establishes scientific evidence closure only; Submission Ready is decided later by the independent Paper Acceptance state machine.`)}</span></div>`;
    return phase(6,"paper-evidence",pick("检查每条论文主张都有证据","CHECK THAT EVERY CLAIM HAS EVIDENCE"),pick("实验结束后，再检查论文中的每条关键主张是否都有对应证据","After experiments finish, check that every important paper claim has matching evidence"),pick("每条核心主张都要指向具体结果：最强基线排除简单解释，消融说明关键组件，分析解释为什么有效和什么时候失败，敏感性与不确定性说明结论是否稳定。系统会把这些关系冻结到“主张账本（Claim Ledger）”和论文证据合同中，最后才做会议格式和补充材料检查。","Every headline claim must point to concrete results: the strongest baseline rules out a simpler explanation, ablations identify the necessary component, analyses explain why it works and when it fails, and sensitivity/uncertainty show stability. Venue formatting and supplements come last."),body);
  };

  api.renderPaperConstructionPhase=(state)=>{
    const pa=state.paper_acceptance||{},index=pa.ledger_index||{},entry=(index.entries||[]).find(row=>row.paper_id==="STRI-ICLR2027")||{},story=entry.latest_story_search||{};
    const guidance=paperDevelopmentGuidance(state),assessment=guidance.guidance?.advisor_assessment||{};
    const body=`${io("已经冻结的科学主张与证据范围","Frozen Scientific Paper Contract","哪条故事线最清楚地组织已有证据，同时不引入还没有证据支持的新结论？成稿以后，事实、引用、数字、表格和 claim 是否仍与冻结证据逐项一致？","Which story most clearly organizes the supported claims without introducing an unsupported claim, and after drafting do facts, citations, numbers, tables, and claims still match the frozen evidence?","获胜故事线 + 版本化成稿 + Post-Draft Integrity 输入","Story Search winner + versioned manuscript + Post-Draft Integrity input")}${flow([[pick("批量提出不同故事线","GENERATE STORY CANDIDATES"),pick("可以调整问题表述、贡献顺序和图表顺序，但不能扩大已经冻结的科学主张","reorder narrative, contributions, and figures without changing the supported claim set")],[pick("先检查有没有越过证据边界","VALIDATE CLAIM BOUNDARY"),pick("任何依赖未支持结论的故事线直接淘汰，不能因为“更好讲”就把新科学结论写进去","invalidate any story that references unsupported claims")],[pick("固定最终故事线","FREEZE WINNER RECEIPT"),pick("最终选择、候选集和科学证据范围都绑定到固定版本，之后可以追溯","content-address the winner, candidate set, and frozen contract")],[pick("按最终故事线形成成稿","BUILD VERSIONED MANUSCRIPT"),pick("没有确定故事线之前不进入正式成稿；成稿本身也必须绑定版本和 manuscript SHA","fail closed without a valid Story Search winner and bind the finished draft to a manuscript SHA")],[pick("成稿先做确定性完整性审计","POST-DRAFT INTEGRITY BEFORE REVIEW"),pick("在独立审稿前先核对事实、引用、所有数字、表格 cell、claim 证据、术语首现和机器化表达；没审到不能当成没问题","before independent review, audit facts, citations, every number, table cells, claim evidence, first-use definitions, and machine-like prose; unaudited content cannot count as clean")]])}<div class="reader-metrics">${metric(entry.current_state==="TARGETED_REPAIR"?"定向修稿中":(entry.current_state||"--"),"STRI 当前论文阶段","STRI current PaperState")}${metric(story.valid_candidates||0,"有效故事线","valid story candidates")}${metric(story.selected_story_id||"--","最终故事线编号","Story Search winner")}${metric((entry.summary||{}).post_draft_integrity_receipts||0,"Post-Draft Integrity 记录","Post-Draft Integrity receipts")}${metric(story.pass?"已确定":"待确定","允许进入成稿","Story→Manuscript gate",story.pass?"good":"warn")}</div><div class="reader-rule"><b>${pick("科学闭环不等于论文已经成熟","Scientific closure is not the same as manuscript maturity")}</b><span>${esc(language==="zh"?(assessment.interpretation_zh||"当前版本先作为初稿；问题与方法方向可以保留，但论文仍需深化。"):(assessment.interpretation_en||"Treat the current versions as initial drafts: preserve the scientific direction while deepening the manuscript."))}</span></div><div class="preflight-card-grid">${paperDevelopmentCards(state)}</div><div class="reader-rule"><b>${pick("写作与完整性是两件事","Writing quality and manuscript integrity are separate")}</b><span>${pick("写作要求是讲人话：每节先说要证明什么，结果先给答案再给数字，首次术语先解释。完整性要求更硬：正文里的事实、引用、数字和表格必须回到 content-addressed source，Writer 不能因为句子更顺就改强 claim 或补一个不存在的数据。","Writing should be plain: state what each section establishes, lead results with the answer, and define terms on first use. Integrity is stricter: manuscript facts, citations, numbers, and tables must return to content-addressed sources; a Writer cannot strengthen a claim or invent a value merely to improve prose.")}</span></div>`;
    return phase(7,"paper-construction",pick("先选出最佳故事线，再按它形成成稿","SEARCH THE STORY, THEN BUILD THE MANUSCRIPT"),pick("科学结论冻结之后，论文还需要找到最清楚、最抗审稿的呈现方式","After scientific conclusions freeze, the paper still needs the clearest and most defensible presentation"),pick("这一阶段不再发明新的科学贡献，只允许在已有证据范围内调整问题表述、贡献顺序和图表叙事。先比较多条故事线，确定最清楚的一条，再据此形成成稿，避免写着写着把没有证据支持的新结论变成论文主线。","Paper Design here does not invent new science: it searches problem framing, contribution order, and figure narrative within supported claims. Manuscript begins only after a content-addressed winner receipt, preventing unsupported conclusions from becoming the main story during writing."),body);
  };

  api.renderReviewRepairPhase=(state)=>{
    const pa=state.paper_acceptance||{},entry=(pa.ledger_index?.entries||[]).find(row=>row.paper_id==="STRI-ICLR2027")||{},modes=entry.mock_pc_modes||{},audit=entry.latest_claim_audit||{},blind=Boolean(modes.BLIND_MANUSCRIPT),artifact=Boolean(modes.ARTIFACT_AWARE),integrityCount=Number((entry.summary||{}).post_draft_integrity_receipts||0);
    const body=`${io("版本化成稿 + 冻结证据 + Post-Draft Integrity receipt + 可核验代码/数据","Versioned manuscript + frozen evidence + Post-Draft Integrity receipt + auditable artifacts","确定性检查先发现哪些事实/引用/数字/表格问题？独立审稿又会因为什么拒稿？修稿后是否仍保持证据边界？","What fact/citation/number/table problems does the deterministic audit catch first, why might independent reviewers still reject the paper, and does the repaired manuscript remain within the evidence boundary?","完整性记录 + 两种模拟审稿 + 定向修稿 + 主张审计 + PDF 质检","integrity receipt + dual Mock PC + Targeted Repair + Claim Audit + PDF QA")}${flow([[pick("先跑成稿完整性审计","DETERMINISTIC POST-DRAFT INTEGRITY"),pick("逐项核对事实、引用、数字、表格 cell、claim 和术语；发现不一致先修文稿，不能靠 reviewer 主观放行","audit facts, citations, numbers, table cells, claims, and first-use definitions before reviewer prose can influence the result")],[pick("只看论文本身模拟审稿","BLIND MANUSCRIPT REVIEW"),pick("像真实审稿人一样只读论文，检查故事是否清楚、贡献是否重要、范围是否过宽、基线是否充分","read like a real reviewer and flag narrative, significance, scope, and baseline risks")],[pick("再结合代码和数据做工件审稿","ARTIFACT-AWARE REVIEW"),pick("检查代码、数据、证据来源和基线实现是否真的支撑论文中的说法","inspect code, data, provenance, support truth, and baseline realization")],[pick("只修真正影响录用的问题","TARGETED REPAIR"),pick("优先处理会改变审稿决定的质疑；如果审稿人建议补新实验，也只能先记录为建议，不能自动开实验","repair decision-critical objections; experiment requests remain advisory and zero-authority")],[pick("修完重新审计主张和 PDF","RE-AUDIT CLAIMS + PDF"),pick("确定性完整性重新跑一遍，再做 Claim Audit；只有主张边界和证据绑定都通过，才检查最终 PDF","rerun deterministic integrity, then Claim Audit; inspect the final PDF only after claim boundaries and evidence bindings pass")]])}<div class="reader-metrics">${metric(integrityCount,"Post-Draft Integrity receipts","Post-Draft Integrity receipts",integrityCount?"good":"warn")}${metric(`${Number(blind)+Number(artifact)}/2`,"两种模拟审稿已完成","Mock PC modes complete",blind&&artifact?"good":"warn")}${metric(entry.current_state==="TARGETED_REPAIR"?"定向修稿中":(entry.current_state||"--"),"当前论文阶段","current PaperState")}${metric(audit.pass?"已通过":"待完成","主张审计","Claim Audit",audit.pass?"good":"warn")}${metric((entry.summary||{}).mock_reviews||0,"已保存模拟审稿记录","Mock PC receipts")}</div><div class="reader-rule"><b>${pick("完整性审计和审稿人的工作不能互相替代","Integrity audit and peer review are different jobs")}</b><span>${pick("确定性审计负责“有没有抄错、引错、写强、漏审”；独立 reviewer 负责“问题重要吗、Insight 是否清楚、实验是否足够、故事是否有说服力”。Reviewer 不能把错误数字投票成正确，完整性脚本也不能替 reviewer 判断研究意义。","Deterministic integrity asks whether anything was copied incorrectly, mis-cited, overstated, or left unaudited. Independent reviewers judge importance, insight, evidence sufficiency, and story. Reviewers cannot vote a wrong number into correctness, and an integrity script cannot judge scientific significance.")}</span></div><div class="reader-rule"><b>${pick("关键状态变化都必须有可核验记录，不能只改网页标签","Transitions require receipts, not UI labels")}</b><span>${pick("Story Search winner 才能进入正式成稿；新流程的成稿先做 Post-Draft Integrity，再进入独立 Mock PC；两种 Mock PC 都完成后才能定向修稿；修稿后重新跑完整性与 Claim Audit，Claim Audit PASS 才允许 PDF QA。后台会核对 receipt hash 和状态迁移，手工改“已通过”标签不会改变真实状态。","A Story Search winner is required for Manuscript; new workflows run Post-Draft Integrity before independent Mock PC; both Mock PC modes are required for Targeted Repair; repair is followed by integrity re-audit and Claim Audit, and Claim Audit PASS is required for PDF QA. Receipt hashes and transitions are replayed, so changing a UI label cannot change the real state.")}</span></div>`;
    return phase(8,"review-repair",pick("先做成稿完整性审计，再模拟真实拒稿风险并定向修稿","AUDIT MANUSCRIPT INTEGRITY, THEN SIMULATE REJECTION RISK AND REPAIR"),pick("确定性核验和独立审稿分工：先查事实数据，再查研究质量","Deterministic integrity and independent review have separate jobs: verify the artifact first, then judge the research"),pick("初稿先经过事实、引用、数字、表格和 claim 的确定性核验；随后才做 Blind 和 Artifact-aware Mock PC。审稿意见驱动定向修稿，但不能自动扩大主张或授权实验；修完以后还要重新做完整性和 Claim Audit，才能进入最终 PDF QA。","The draft first passes deterministic checks over facts, citations, numbers, tables, and claims, then Blind and Artifact-aware Mock PC. Reviewer findings drive targeted repair without expanding claims or authorizing experiments; deterministic integrity and Claim Audit run again after repair before final PDF QA."),body);
  };

  api.renderSubmissionClosurePhase=(state)=>{
    const pa=state.paper_acceptance||{},idx=pa.ledger_index||{},entry=(idx.entries||[]).find(row=>row.paper_id==="STRI-ICLR2027")||{},ci=entry.latest_manuscript_ci||{},pre=entry.latest_prebuttal||{},ready=entry.latest_submission_readiness||{},auth=entry.authority||{};
    const body=`${io("Post-Draft Integrity、主张审计和 PDF 质检后的最终成稿 + 模拟审稿质疑","Final manuscript after Post-Draft Integrity, Claim Audit, and PDF QA + reviewer objections","最可能导致拒稿的问题是否已经回答？9 项 Manuscript CI、必要的 Post-Draft Integrity 和预答辩是否都通过？是否已有明确人工投稿授权？","Do all decision-critical objections, the nine Manuscript CI checks, required Post-Draft Integrity, and Prebuttal pass, and is explicit human submission authority present?","预答辩记录 + 投稿就绪判断 + 真实投稿/答辩记录","Prebuttal + Submission Readiness + Submitted/Rebuttal receipts")}${flow([[pick("提前回答最危险的审稿问题","PREBUTTAL"),pick("把最可能影响录用的质疑提前写成有证据支持的回答","pre-answer decision-critical objections with evidence-backed responses")],[pick("判断是否已经准备好投稿","SUBMISSION READY"),pick("成稿完整性、9 项 Manuscript CI、Claim/PDF QA 和预答辩按当前合同全部通过，系统才会给出“可以投稿”的判断","emit readiness only when manuscript integrity, the nine CI checks, Claim/PDF QA, and Prebuttal satisfy the current contract")],[pick("由作者完成真实投稿","SUBMITTED"),pick("必须有明确的外部人工授权；系统本身永远不能替作者点击提交","requires explicit external human authority; the system never grants itself submission permission")],[pick("处理真实审稿意见","REBUTTAL"),pick("真实审稿意见分别进入论文修复、已有证据解释，或明确重开科学问题","route real reviewer feedback to existing evidence, paper repair, or an explicit scientific reopen")]])}<div class="reader-metrics">${metric(`${ci.passed||0}/${ci.required||9}`,"文稿一致性检查","Manuscript CI")}${metric(pre.pass?"已完成":"待完成","预答辩","Prebuttal")}${metric(ready.submission_ready?"已就绪":"未就绪","投稿准备状态","Submission Readiness")}${metric(idx.summary?.scientific_holds||0,"仍有科学问题暂缓的论文","papers on scientific hold")}</div><div class="reader-rule"><b>${pick("“已经准备好投稿”和“有权真正提交”是两回事","Readiness and authority are different concepts")}</b><span>${pick(`系统可以检查论文是否已经满足投稿条件，但自动投稿权限始终为 0。即使所有质检都通过，也只是得到“已经准备好投稿”的记录；真实提交必须由作者明确授权并完成。`,`Paper Acceptance automatic authority: scientific=${auth.scientific?1:0}, experiment=${auth.experiment?1:0}, GPU=${auth.gpu?1:0}, submission=${auth.submission?1:0}. Even when all QA passes, the workflow only emits readiness; real Submitted state requires separate external human authority.`)}</span></div>`;
    return phase(9,"submission-closure",pick("把投稿准备、人工授权和真实审稿纳入同一闭环","CLOSE PREBUTTAL, SUBMISSION AUTHORITY, AND REAL REVIEW IN THE SAME LEDGER"),pick("真正投稿前，还必须完成预答辩、文稿检查和人工授权","Submission is not one Boolean button; it is the final set of fail-closed transitions"),pick("先提前回答最可能导致拒稿的问题，再完成 9 项文稿一致性检查。全部通过以后，系统只能判断“论文已经准备好投稿”；真正提交仍必须由作者授权。投稿后的真实审稿意见再决定是只修论文，还是明确重开科学问题。","Prebuttal must resolve decision-critical objections and Manuscript CI must pass. Submission Ready still has zero submission authority; real submission requires external human approval. Real reviewer feedback then enters Rebuttal and is classified as paper repair or a formal scientific reopen."),body);
  };

  api.renderSystemLearningPhase=(state)=>{
    const memoryState=researchMemory(state),m=state.scientific_meta_trace?.summary||{},f=state.failure_asset_library?.summary||{},r=state.research_system_replay?.summary||{},e=state.external_system_learning?.summary||{},v=state.experiment_value_scheduler?.summary||{},graph=state.scientific_research_graph?.summary||{},memory=memoryState.summary||{},memoryLint=memoryState.lint?.summary||{},assurance=state.research_harness_assurance?.summary||{},funnel=state.search_funnel_telemetry?.summary||{};
    const discoveryLessons=(memoryState.entries||[]).filter(row=>row&&row.kind==="DISCOVERY_LESSON");
    const discoveryLessonCards=discoveryLessons.map(row=>`<article class="system-lesson persistence" data-discovery-lesson="${esc(row.memory_id||"")}"><header><span>${esc(row.memory_class||"DISCOVERY_LESSON")}</span><h4 data-toc="false">${esc(row.title||row.memory_id||"Discovery lesson")}</h4></header><dl><div><dt>${pick("经验","Lesson")}</dt><dd>${esc(row.summary||"--")}</dd></div><div><dt>${pick("下次预检","Pre-check")}</dt><dd>${esc(row.reusable_precheck||"--")}</dd></div><div><dt>${pick("重开条件","Reopen")}</dt><dd>${esc(row.reopen_condition||"--")}</dd></div></dl></article>`).join("");
    const body=`${io("最终决策、原始日志/轨迹、论文证据和失败原因","Final decisions, raw logs/traces, paper evidence, and failure causes","为什么继续或停止？什么新证据出现时值得重开？下一次最便宜应该先检查什么？","Which lessons should become automatic future checks, and which only show what happened under one model/data/setup?","当前状态记录、失败案例、重开条件和可自动重放的防错测试","Current-state record, failure-case library, and replayable regression checks")}${flow([[pick("只保留一个当前结论","ONE CURRENT DECISION"),pick("旧记录解释历史，但不能覆盖最新经过审计的状态","history explains the past but cannot overwrite the latest audited state")],[pick("记录为什么得出结论","RECORD WHY"),pick("保存决定结论的关键证据，以及还有哪些未知项","assumption · prediction · evidence · next uncertainty")],[pick("保存明确的重开条件","SAVE FAILURE CASES"),pick("记录什么条件下失败，以及只有出现什么新证据才值得重新研究","failure conditions · cause · evidence required to reopen")],[pick("自动重放旧案例","REPLAY OLD CASES"),pick("系统改动后检查已知错误不会重新放行，已知有效流程也不会被误停","after changes, known bad cases stay blocked and known good cases stay accepted")],[pick("把有效经验变成下一轮的廉价前置检查","LEARN FROM OTHER SYSTEMS"),pick("先检查最容易失败、成本最低的条件，再决定是否进入昂贵搜索或实验","confirm a local gap, test the smallest case, adopt only if it helps")]])}<div class="reader-metrics">${metric(m.unresolved_principles||0,"仍未解释清楚的科学问题","unresolved scientific questions")}${metric(f.assets||0,"已保存失败案例","saved failure cases")}${metric(`${r.passed||0}/${r.cases||0}`,"防错案例重放通过","regression replays passed")}${metric(v.candidates||0,"正在比较是否值得运行的实验","experiments being compared for value")}${metric(e.systems_reviewed||0,"已审查外部科研系统","external research systems reviewed")}${metric(memory.discovery_lessons||0,"发现阶段失败经验","discovery lessons")}${metric(memory.review_lessons||0,"已沉淀审稿模式","typed review lessons")}${metric(memory.paper_development_guidance||0,"论文深化准则","paper-development guidance")}</div>${discoveryLessons.length?`<section class="system-lessons" data-discovery-lesson-section><div class="system-lessons-head"><div><h3>${pick("本轮 Discovery 失败经验已进入可检索前端记忆","Discovery lessons are now visible in the retrievable research memory")}</h3><p class="section-intro">${pick("这里逐条展示本轮从 source grounding、same-information reduction、Debate protocol 与 support censoring 中沉淀的经验。它们只用于下一轮检索与廉价预检，科学权限始终为 0。","These records expose the lessons distilled from source grounding, same-information reductions, debate protocol failures, and support censoring. They guide retrieval and cheap pre-checks only and always carry zero scientific authority.")}</p></div><div class="system-retro-score"><b>${discoveryLessons.length}</b><span>${pick("条 DISCOVERY_LESSON","DISCOVERY_LESSON records")}</span><small>${pick("前端来自 canonical Research Memory projection","rendered from the canonical Research Memory projection")}</small></div></div><div class="system-lesson-grid">${discoveryLessonCards}</div></section>`:""}<div class="reader-termination-block"><div class="reader-termination-head"><span class="system-kicker">TERMINATION & MEMORY AUTHORITY</span><h4 data-toc="false">${pick("终止结论、搜索记忆和历史 snapshot 必须分层读取","Read terminal decisions, search memory, and historical snapshots as separate authority layers")}</h4><p>${pick("系统会保存很多旧状态，但只有当前 canonical ledger / receipt 能回答“现在是什么结论”。关闭一个对象只改变它自己的状态和后续检索约束，不会把科学权限横向转移给另一个候选。","The system preserves many historical states, but only the current canonical ledger/receipt answers what is true now. Closing one object changes its own state and future retrieval constraints; it never transfers scientific authority sideways to another candidate.")}</p></div><div class="reader-termination-matrix"><article><header><small>CURRENT AUTHORITY</small><b>${pick("当前 canonical 状态优先于所有历史 snapshot","Current canonical state outranks every historical snapshot")}</b></header><p>${pick("旧 snapshot 只解释当时看到过什么。它可以用于 provenance、复盘和恢复文件，但不能覆盖后来已经由 ledger、receipt 或 terminal decision 确认的当前结论。恢复工作树也不能把旧投影重新变成 current truth。","An old snapshot explains what was visible at that time. It may support provenance, replay, or file recovery, but it cannot override a later ledger, receipt, or terminal decision. Restoring a worktree never turns an old projection back into current truth.")}</p><footer>${pick("历史可读 · 当前权限 0","historical readability · zero current authority")}</footer></article><article><header><small>EXACT REDUCTION</small><b>${pick("Exact reduction 终止不能靠重复实验复活","Exact-reduction closure cannot be revived by repeating the same experiment")}</b></header><p>${pick("如果在同信息、同范围下，更简单的成熟解释已经完整吸收核心预测或机制，这个 scientific object 可以进入 PRINCIPLE_STOP。继续增加同类 seed、GPU 或重复相同测量不会改变这一结论。重开需要新的第一手证据改变前提，或提出实质不同的科学对象、预测与新论文合同。","If a simpler mature explanation fully absorbs the core prediction or mechanism under the same information and scope, that scientific object may enter PRINCIPLE_STOP. More same-kind seeds, GPU, or repeated measurements do not reopen it. Reopening requires new primary evidence that changes the premises, or a materially different scientific object, prediction, and paper contract.")}</p><footer>${pick("可形成 persistent scientific closure","eligible for persistent scientific closure")}</footer></article><article><header><small>SEARCH / REALIZATION</small><b>${pick("Search、Support、Protocol、Realization STOP 只约束对应层","Search, Support, Protocol, and Realization STOP constrain only their own layer")}</b></header><p>${pick("搜索被已有解释吸收、当前 support 不足、协议不可辨识或实现失败，都应该留下可检索 dead-end / hold 记录，避免下次重复踩同一个坑；它们不等价于整个研究方向被科学否定，也不能写成永久黑名单。","A reduced search branch, missing support, non-identifiable protocol, or failed realization should leave a retrievable dead-end/hold record so the next run avoids the same mistake. None of these implies that the whole research direction is scientifically false, and none becomes a permanent blacklist.")}</p><footer>${pick("只更新对应层 · principle authority 0","update the affected layer only · zero principle authority")}</footer></article><article><header><small>NO INHERITED PASS</small><b>${pick("关闭一个 Idea 不会让下一个 Idea 自动晋级","Closing one idea never auto-promotes the next idea")}</b></header><p>${pick("一个候选被关闭后，scheduler 可以把注意力移向别的候选，Research Memory 也可以提醒下一轮避开旧 reduction basin；但新候选仍必须独立通过第一手证据、same-information reduction、Problem Gate 和后续 Paper Design。排序优先级不属于科学证据。","After one candidate closes, the scheduler may move attention elsewhere and Research Memory may steer the next search away from the old reduction basin. The next candidate must still independently pass primary evidence, same-information reduction, the Problem Gate, and Paper Design. Scheduling priority is never scientific evidence.")}</p><footer>${pick("调度可以继承 · 科学 PASS 不能继承","scheduling may inherit priority · scientific PASS never inherits")}</footer></article></div></div><div class="reader-rule"><b>${pick("科研记忆不是失败方向黑名单","The failure wiki is now consumed by the next search and experiment design")}</b><span>${pick(`当前记忆中有 ${memory.search_closures||0} 条搜索层停止记录、${memory.scientific_closures||0} 条真正科学关闭、${memory.holds||0} 条暂缓、${memory.open_questions||0} 个开放问题、${memory.discovery_lessons||0} 条 Discovery 失败经验，以及 ${memory.review_lessons||0} 条从 Paper Mock PC 压缩出的审稿模式、${memory.paper_development_guidance||0} 条人工论文深化准则。Discovery 经验、审稿模式与深化准则都只作为下一轮检索 / Paper Design / Manuscript precheck，不保存原始评语，也不会自动授权实验；它们用于让下一篇论文更早检查完成度和重复风险。`,`Current Wiki: search closures=${memory.search_closures||0}, true scientific closures=${memory.scientific_closures||0}, HOLD=${memory.holds||0}, Failure Assets=${memory.failure_assets||0}, Success Assets=${memory.success_assets||0}, open questions=${memory.open_questions||0}, discovery lessons=${memory.discovery_lessons||0}, typed review lessons=${memory.review_lessons||0}, and paper-development guidance=${memory.paper_development_guidance||0}. Discovery lessons, review lessons, and development guidance are structured prechecks rather than raw prose and grant no experiment authority. Paper Design and manuscript revision use them as early maturity/risk checks.`)}</span></div><div class="reader-rule"><b>${pick("一次运行故障不会改变长期科学判断","One operational glitch cannot poison long-term research memory")}</b><span>${pick(`单次运行或环境故障只保留为临时记录；同类问题重复出现后，才会升级成下一轮的系统前置检查。真正改变长期科学判断的，必须是与科学主张直接相关的证据。`,`Memory durability is typed as transient / recurring-systemic / scientific. A one-off execution/runtime failure is transient and excluded from prompts; recurrence is required before it becomes a systemic precheck.`)}</span></div><div class="reader-rule"><b>${pick("图谱记录的是“什么证据支持什么结论”","The Research Graph is not a failed-idea blacklist")}</b><span>${pick(`论文、研究问题、主张、实验、失败案例和科学关闭分别保存，因此实验失败不会自动变成“整个方向失败”。当前图谱有 ${graph.nodes||0} 个节点、${graph.edges||0} 条关系，其中实验节点 ${graph.experiment_nodes||0} 个。`,`The graph keeps papers, ideas, claims, experiments, core principles, failure assets, and scientific closures as distinct objects. Current nodes=${graph.nodes||0}, edges=${graph.edges||0}, experiment nodes=${graph.experiment_nodes||0}.`)}</span></div>`;
    return phase(10,"system-learning",pick("记住为什么继续、为什么停止、为什么被接收或拒绝","REMEMBER WHY WE CONTINUED, STOPPED, ACCEPTED, OR WERE REJECTED"),pick("科研结论与真实投稿结果都要留下下次可以直接使用的原因","Scientific decisions and real submission outcomes should both leave reusable reasons for the next run"),pick("系统保存的不只是一句“这个方向失败了”，还记录它在哪些数据、模型和假设范围内失败，哪条证据真正决定了科学结论，哪些审稿质疑影响了投稿，出现什么新证据才值得重开，以及下一次最便宜应该先检查什么。这样后续 Agent 不会重复旧错误，也不会把局部结果或一次审稿意见误写成永久真理。","The system records more than that a direction failed: it stores the data/model/assumption scope, which evidence decided the science, which reviewer objections actually affected submission, what new evidence justifies reopening, and the cheapest next check. This prevents both local results and one review cycle from becoming permanent truth."),body);
  };
})();
